using Microsoft.Extensions.Logging;

namespace MyMauiApp;

public static class MauiProgram
{
    public static MauiApp CreateMauiApp()
    {
        var builder = MauiApp.CreateBuilder();
        builder
            .UseMauiApp<App>()
            .ConfigureFonts(fonts =>
            {
                fonts.AddFont("OpenSans-Regular.ttf", "OpenSansRegular");
            });

        // --- Services ---

        // HttpClient: Singleton so we reuse one connection pool app-wide.
        // In production, consider IHttpClientFactory for resilience.
        builder.Services.AddSingleton<HttpClient>();

        // DataService: Singleton because it wraps HttpClient and holds no
        // per-user/per-page state. One instance serves every consumer.
        builder.Services.AddSingleton<IDataService, DataService>();

        // --- ViewModels ---

        // Transient: each page navigation gets its own fresh ViewModel,
        // avoiding stale state when the user navigates back and forth.
        builder.Services.AddTransient<MainViewModel>();
        builder.Services.AddTransient<DetailViewModel>();

        // --- Pages ---

        // Transient: MAUI creates a new page instance per navigation,
        // each receiving its own ViewModel via constructor injection.
        builder.Services.AddTransient<MainPage>();
        builder.Services.AddTransient<DetailPage>();

#if DEBUG
        builder.Logging.AddDebug();
#endif

        return builder.Build();
    }
}

